def flatten_dict(d, sep="."):
    """
    Return a new dictionary with nested dictionaries flattened into a single level.
    Keys are joined by `sep`. Only dictionaries are descended into; other values
    (including lists) are kept as they are. Empty nested dictionaries are kept
    as empty dictionaries under their key. The input dictionary is not modified.
    """
    if not isinstance(d, dict):
        raise TypeError("flatten_dict expects a dictionary as input")

    result = {}

    def _flatten(current, prefix):
        for key, value in current.items():
            if not isinstance(key, str):
                raise TypeError("All keys must be strings")
            new_key = f"{prefix}{sep}{key}" if prefix else key
            if isinstance(value, dict):
                if value:
                    _flatten(value, new_key)
                else:
                    result[new_key] = {}
            else:
                result[new_key] = value

    _flatten(d, "")
    return result
